"use client";
import { useState, useTransition } from "react";
import { Eye, EyeOff, ImagePlus, Pencil, Trash2 } from "lucide-react";
import { deleteBusinessPost, saveBusinessPost, setBusinessPostPublished } from "@/app/actions/business-timeline";
import { toast } from "sonner";
type Post={id:string;caption:string;images:string[];published:boolean;createdAt:string;_count:{likes:number;comments:number}};
export default function TimelineManager({storeName,posts}:{storeName:string;posts:Post[]}){const [edit,setEdit]=useState<Post|null>(null);const [busy,start]=useTransition();const act=(job:()=>Promise<{error?:string}>)=>start(async()=>{const r=await job();r.error?toast.error(r.error):(toast.success("Timeline updated"),location.reload())});return <div className="mx-auto max-w-5xl px-4 py-7 sm:px-7"><div className="mb-6"><p className="text-xs font-black uppercase tracking-[.18em] text-[#D4450A]">Business marketing</p><h1 className="mt-1 text-3xl font-black">Timeline Studio</h1><p className="mt-2 max-w-2xl text-sm text-zinc-500">Post arrivals, offers and daily business updates to customers who follow {storeName}. Images live on the LinkWe media CDN, not in the database.</p></div><form onSubmit={e=>{e.preventDefault();const form=e.currentTarget;act(async()=>{const r=await saveBusinessPost(new FormData(form));if(!r.error){form.reset();setEdit(null)}return r})}} className="rounded-[28px] border border-zinc-200 bg-white p-5 shadow-sm"><input type="hidden" name="postId" value={edit?.id||""}/>{edit?.images.map(url=><input key={url} type="hidden" name="existingImages" value={url}/>)}<textarea name="caption" defaultValue={edit?.caption||""} key={edit?.id||"new"} rows={4} maxLength={2200} placeholder="Tell followers what is new at your business…" className="w-full resize-none rounded-2xl bg-zinc-50 p-4 text-sm outline-none focus:ring-2 focus:ring-orange-200"/><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-zinc-200 px-4 py-3 text-sm font-bold"><ImagePlus size={18}/> Add images<input name="images" type="file" accept="image/jpeg,image/png,image/webp" multiple className="hidden"/></label><button disabled={busy} className="rounded-xl bg-[#D4450A] px-5 py-3 text-sm font-black text-white">{edit?"Save changes":"Publish post"}</button>{edit&&<button type="button" onClick={()=>setEdit(null)} className="text-sm font-bold text-zinc-500">Cancel</button>}<span className="text-xs text-zinc-400">Up to 10 JPG, PNG or WebP images</span></div></form><div className="mt-7 grid gap-5 sm:grid-cols-2">{posts.map(post=><article key={post.id} className="overflow-hidden rounded-3xl border border-zinc-200 bg-white shadow-sm">{post.images[0]&&<img src={post.images[0]} alt="" className="aspect-video w-full object-cover"/>}<div className="p-4"><p className="line-clamp-3 whitespace-pre-wrap text-sm leading-6">{post.caption||"Image post"}</p><p className="mt-3 text-xs font-bold text-zinc-400">{post._count.likes} likes · {post._count.comments} comments · {post.published?"Live":"Hidden"}</p><div className="mt-4 flex gap-2"><button onClick={()=>setEdit(post)} className="rounded-xl bg-zinc-100 p-2.5" aria-label="Edit"><Pencil size={17}/></button><button onClick={()=>act(()=>setBusinessPostPublished(post.id,!post.published))} className="rounded-xl bg-zinc-100 p-2.5" aria-label={post.published?"Hide":"Publish"}>{post.published?<EyeOff size={17}/>:<Eye size={17}/>}</button><button onClick={()=>confirm("Delete this post permanently?")&&act(()=>deleteBusinessPost(post.id))} className="rounded-xl bg-rose-50 p-2.5 text-rose-700" aria-label="Delete"><Trash2 size={17}/></button></div></div></article>)}</div></div>}
